using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Collections.Generic;using System.Text.Json;using UnityEngine;using UnityEngine.UI;using UnityEngine.Events;using HarmonyLib;using Il2CppInterop.Runtime;using MDPro3;using MDPro3.Servant;
namespace DuelStructure {
 static class NativeLogArchive {
  public sealed class Document{public int Version=1,Point;public Context State;public List<Entry> Rows=new List<Entry>();}
  public sealed class CardRef{public int Code;public uint Player,Location,Sequence;public int Position;}
  public sealed class Context{public int ChainIndex;public bool Pendulum;public uint SummonReason;public List<CardRef> Chain=new List<CardRef>(),Targets=new List<CardRef>();public CardRef LastMove,Confirmed,Attacking;}
  static CardRef Reference(MDPro3.GameCard card){if(card==null||card.p==null)return null;var p=card.p;return new CardRef{Code=card.GetData().Id,Player=p.controller==0?(uint)Host.Session.View:(uint)(1-Host.Session.View),Location=p.location,Sequence=p.sequence,Position=p.position};}
  static List<CardRef> References(Il2CppSystem.Collections.Generic.List<MDPro3.GameCard> cards){var result=new List<CardRef>();for(int i=0;i<cards.Count;i++)result.Add(Reference(cards[i]));return result;}
  static Context pendingContext;
  public static void Reset(){pendingContext=null;cardImages.Clear();importedPrefabs.Clear();sprites=null;materials=null;}
  public static void QueueContext(Context context){pendingContext=context;}
  public static void RestoreQueuedContext(){if(pendingContext==null)return;var context=pendingContext;pendingContext=null;RestoreContext(context);}
  public static Context CaptureContext(){if(pendingContext!=null)return pendingContext;var log=Program.instance.ocgcore.messageDispatcher.log;return new Context{ChainIndex=MDPro3.Duel.LogMessage.chainSolvingIndex,Pendulum=log.inPendulumSummon,SummonReason=log.lastSpSummonReason,Chain=References(log.cardsInChain),Targets=References(log.cardsBeTarget),LastMove=Reference(log.lastMoveCard),Confirmed=Reference(log.lastConfirmedCard),Attacking=Reference(log.attackingCard)};}
  static MDPro3.GameCard Resolve(CardRef reference){if(reference==null)return null;var gps=new GPS{controller=reference.Player==(uint)Host.Session.View?0u:1u,location=reference.Location,sequence=reference.Sequence,position=reference.Position};var card=Program.instance.ocgcore.GCS_Get(gps);if(card!=null&&reference.Code>0)card.SetCode(reference.Code);return card;}
  public static void RestoreContext(Context context){if(context==null)return;var log=Program.instance.ocgcore.messageDispatcher.log;log.cardsInChain.Clear();foreach(var reference in context.Chain)log.cardsInChain.Add(Resolve(reference));log.cardsBeTarget.Clear();foreach(var reference in context.Targets)log.cardsBeTarget.Add(Resolve(reference));MDPro3.Duel.LogMessage.chainSolvingIndex=context.ChainIndex;log.inPendulumSummon=context.Pendulum;log.lastSpSummonReason=context.SummonReason;log.lastMoveCard=Resolve(context.LastMove);log.lastConfirmedCard=Resolve(context.Confirmed);log.attackingCard=Resolve(context.Attacking);}
  public sealed class Entry{public int Point,View;public bool Summon,Search,Opening;public string Edit,Prefab;public Node Root;}
  public sealed class Node{public string Name;public bool Active;public float[] Rect;public Caption Text;public Picture Image;public Face Raw;public bool Button;public List<Node> Children=new List<Node>();}
  public sealed class Caption{public string Value;public int Size,Align,Style,Horizontal,Vertical;public bool Fit;public float Spacing;public float[] Color;}
  public sealed class Picture{public string Sprite,Material;public float[] Color;public bool Enabled,Aspect;public int Type;public float Fill;}
  public sealed class Face{public int Code;public string Material;public float[] Color,Uv;public bool Enabled;}
  sealed class CardImage{public int Instance,Code;}
  static readonly Dictionary<IntPtr,CardImage> cardImages=new Dictionary<IntPtr,CardImage>();
  static readonly HashSet<string> prefabs=new HashSet<string>{"DuelLogLpChange","DuelLogSingleCard","DuelLogSingleCard2","DuelLogText","DuelLogText2","DuelLogAttack","DuelLogChaining","DuelLogCounter","DuelLogNewPhase","DuelLogNewTurn","DuelLogTextWithCard","DuelLogTextWithCard2"};
  static readonly JsonSerializerOptions options=new JsonSerializerOptions{IncludeFields=true,MaxDepth=96};
  static readonly HashSet<string> importedPrefabs=new HashSet<string>();static Dictionary<string,Sprite> sprites;static Dictionary<string,Material> materials;
  public static void Track(RawImage image,int code){if(image!=null)cardImages[image.Pointer]=new CardImage{Instance=image.GetInstanceID(),Code=code};}
  public static int KnownCode(RawImage image)=>Code(image);
  public static string Prefab(GameObject go){string name=go.name.Replace("(Clone)","").Trim();if(!prefabs.Contains(name))throw new InvalidDataException("无法保存的原生记录类型："+name);return name;}
  static float[] ColorData(Color c)=>new[]{c.r,c.g,c.b,c.a};static Color ReadColor(float[] a)=>new Color(a[0],a[1],a[2],a[3]);
  static string SpriteKey(Sprite s)=>s==null?"":s.name+"|"+(s.texture==null?"":s.texture.name)+"|"+s.rect.ToString();
  static string MaterialKey(Material m){if(m==null||m==Graphic.defaultGraphicMaterial)return "";if(m==OcgCore.myProtector)return "@back:"+Host.Session.View;if(m==OcgCore.opProtector)return "@back:"+(1-Host.Session.View);return m.name;}
  static int Code(RawImage image){if(cardImages.TryGetValue(image.Pointer,out var entry)&&entry.Instance==image.GetInstanceID())return entry.Code;return image.texture!=null&&int.TryParse(image.texture.name,out int code)?code:0;}
  public static Node Capture(GameObject go){var r=go.GetComponent<RectTransform>();var node=new Node{Name=go.name,Active=go.activeSelf,Rect=new[]{r.anchorMin.x,r.anchorMin.y,r.anchorMax.x,r.anchorMax.y,r.pivot.x,r.pivot.y,r.anchoredPosition.x,r.anchoredPosition.y,r.sizeDelta.x,r.sizeDelta.y,r.localScale.x,r.localScale.y,r.localScale.z,r.localEulerAngles.x,r.localEulerAngles.y,r.localEulerAngles.z}};
   var t=go.GetComponent<Text>();if(t!=null)node.Text=new Caption{Value=t.text,Size=t.fontSize,Align=(int)t.alignment,Style=(int)t.fontStyle,Horizontal=(int)t.horizontalOverflow,Vertical=(int)t.verticalOverflow,Fit=t.resizeTextForBestFit,Spacing=t.lineSpacing,Color=ColorData(t.color)};
   var image=go.GetComponent<Image>();if(image!=null)node.Image=new Picture{Sprite=SpriteKey(image.sprite),Material=MaterialKey(image.material),Color=ColorData(image.color),Enabled=image.enabled,Aspect=image.preserveAspect,Type=(int)image.type,Fill=image.fillAmount};
   var raw=go.GetComponent<RawImage>();if(raw!=null)node.Raw=new Face{Code=Code(raw),Material=MaterialKey(raw.material),Color=ColorData(raw.color),Enabled=raw.enabled,Uv=new[]{raw.uvRect.x,raw.uvRect.y,raw.uvRect.width,raw.uvRect.height}};
   node.Button=go.GetComponent<Button>()!=null;for(int i=0;i<go.transform.childCount;i++)node.Children.Add(Capture(go.transform.GetChild(i).gameObject));return node;
  }
  public static byte[] Encode(Document document){byte[] json=JsonSerializer.SerializeToUtf8Bytes(document,options);if(json.Length>32*1024*1024)throw new InvalidDataException("效果记录数据过大");using(var result=new MemoryStream()){using(var gzip=new GZipStream(result,System.IO.Compression.CompressionLevel.Optimal,true))gzip.Write(json,0,json.Length);return result.ToArray();}}
  public static Document Decode(byte[] bytes,int point){if(bytes==null||bytes.Length>32*1024*1024)throw new InvalidDataException("效果记录数据无效");using(var compressed=new MemoryStream(bytes))using(var gzip=new GZipStream(compressed,CompressionMode.Decompress))using(var plain=new MemoryStream()){var buffer=new byte[65536];int n;while((n=gzip.Read(buffer,0,buffer.Length))>0){if(plain.Length+n>32*1024*1024)throw new InvalidDataException("效果记录展开后过大");plain.Write(buffer,0,n);}var doc=JsonSerializer.Deserialize<Document>(plain.ToArray(),options);if(doc==null||doc.Version!=1||doc.Point!=point||doc.Rows==null||doc.Rows.Count>100000)throw new InvalidDataException("效果记录格式或时点无效");if(doc.State!=null){if(doc.State.Chain==null||doc.State.Targets==null||doc.State.Chain.Count>256||doc.State.Targets.Count>1024||doc.State.ChainIndex<0||doc.State.ChainIndex>256)throw new InvalidDataException("效果记录连锁状态无效");foreach(var card in doc.State.Chain.Concat(doc.State.Targets).Concat(new[]{doc.State.LastMove,doc.State.Confirmed,doc.State.Attacking}))if(card!=null&&(card.Player>1||card.Code<0||card.Sequence>1024))throw new InvalidDataException("效果记录卡片引用无效");}int count=0;foreach(var row in doc.Rows){if(row.Point<1||row.Point>point||row.View<0||row.View>1||!prefabs.Contains(row.Prefab)||row.Edit!=null&&row.Edit.Length>65536)throw new InvalidDataException("效果记录项目无效");Validate(row.Root,0,ref count);}return doc;}}
  static void Array(float[] a,int length){if(a==null||a.Length!=length||a.Any(f=>float.IsNaN(f)||float.IsInfinity(f)||Math.Abs(f)>1000000))throw new InvalidDataException("效果记录布局无效");}
  static void Validate(Node n,int depth,ref int count){if(n==null||depth>24||++count>500000||n.Name==null||n.Name.Length>256||n.Children==null||n.Children.Count>256)throw new InvalidDataException("效果记录节点无效");Array(n.Rect,16);if(n.Text!=null){if(n.Text.Value==null||n.Text.Value.Length>65536||n.Text.Size<0||n.Text.Size>256||n.Text.Align<0||n.Text.Align>8||n.Text.Style<0||n.Text.Style>3||n.Text.Horizontal<0||n.Text.Horizontal>1||n.Text.Vertical<0||n.Text.Vertical>1)throw new InvalidDataException("效果记录文字无效");Array(n.Text.Color,4);}if(n.Image!=null){Array(n.Image.Color,4);if(n.Image.Type<0||n.Image.Type>3||n.Image.Sprite==null||n.Image.Sprite.Length>1024||n.Image.Material==null||n.Image.Material.Length>512)throw new InvalidDataException("效果记录图标无效");}if(n.Raw!=null){Array(n.Raw.Color,4);Array(n.Raw.Uv,4);if(n.Raw.Code<0||n.Raw.Material==null||n.Raw.Material.Length>512)throw new InvalidDataException("效果记录卡图无效");}foreach(var child in n.Children)Validate(child,depth+1,ref count);}
  static T Add<T>(GameObject go)where T:Component=>go.GetComponent<T>()??go.AddComponent(Il2CppType.Of<T>()).Cast<T>();
  static void ResourcesCache(){sprites=new Dictionary<string,Sprite>();foreach(var s in Resources.FindObjectsOfTypeAll<Sprite>())if(s!=null)sprites[SpriteKey(s)]=s;materials=new Dictionary<string,Material>();foreach(var m in Resources.FindObjectsOfTypeAll<Material>())if(m!=null&&!materials.ContainsKey(m.name))materials[m.name]=m;}
  static Material ReadMaterial(string key){if(string.IsNullOrEmpty(key))return null;if(key.StartsWith("@back:")){return key.Substring(6)==Host.Session.View.ToString()?OcgCore.myProtector:OcgCore.opProtector;}return materials.TryGetValue(key,out var value)?value:null;}
  public static void BeginImport(){importedPrefabs.Clear();ResourcesCache();}
  public static GameObject Create(Entry entry){var go=ABLoader.LoadMasterDuelGameObject(entry.Prefab);if(importedPrefabs.Add(entry.Prefab))ResourcesCache();Font font=go.GetComponentInChildren<Text>(true)?.font;Apply(entry.Root,go,font,go.transform.childCount>4?go.transform.GetChild(4).gameObject:null);go.SetActive(true);return go;}
  static void Apply(Node n,GameObject go,Font font,GameObject cardTemplate){go.name=n.Name;var rect=Add<RectTransform>(go);var a=n.Rect;rect.anchorMin=new Vector2(a[0],a[1]);rect.anchorMax=new Vector2(a[2],a[3]);rect.pivot=new Vector2(a[4],a[5]);rect.anchoredPosition=new Vector2(a[6],a[7]);rect.sizeDelta=new Vector2(a[8],a[9]);rect.localScale=new Vector3(a[10],a[11],a[12]);rect.localEulerAngles=new Vector3(a[13],a[14],a[15]);
   if(n.Text!=null){var t=Add<Text>(go);if(t.font==null)t.font=font;t.text=n.Text.Value;t.fontSize=n.Text.Size;t.alignment=(TextAnchor)n.Text.Align;t.fontStyle=(FontStyle)n.Text.Style;t.horizontalOverflow=(HorizontalWrapMode)n.Text.Horizontal;t.verticalOverflow=(VerticalWrapMode)n.Text.Vertical;t.resizeTextForBestFit=n.Text.Fit;t.lineSpacing=n.Text.Spacing;t.color=ReadColor(n.Text.Color);t.raycastTarget=false;}
   if(n.Image!=null){var image=Add<Image>(go);if(sprites.TryGetValue(n.Image.Sprite,out var sprite))image.sprite=sprite;image.material=ReadMaterial(n.Image.Material);image.color=ReadColor(n.Image.Color);image.enabled=n.Image.Enabled;image.type=(Image.Type)n.Image.Type;image.fillAmount=n.Image.Fill;image.preserveAspect=n.Image.Aspect;}
   if(n.Raw!=null){var raw=Add<RawImage>(go);raw.color=ReadColor(n.Raw.Color);raw.enabled=n.Raw.Enabled;raw.material=ReadMaterial(n.Raw.Material);raw.uvRect=new Rect(n.Raw.Uv[0],n.Raw.Uv[1],n.Raw.Uv[2],n.Raw.Uv[3]);Track(raw,n.Raw.Code);raw.texture=null;if(n.Raw.Code>0){_ = Program.instance.texture_.LoadCardToRawImageWithoutMaterialAsync(raw,n.Raw.Code,true);}}
   while(go.transform.childCount>n.Children.Count)UnityEngine.Object.DestroyImmediate(go.transform.GetChild(go.transform.childCount-1).gameObject);
   for(int i=0;i<n.Children.Count;i++){GameObject child;if(i<go.transform.childCount)child=go.transform.GetChild(i).gameObject;else if(n.Children[i].Raw!=null&&cardTemplate!=null&&cardTemplate.GetComponent<RawImage>()!=null)child=UnityEngine.Object.Instantiate(cardTemplate,go.transform);else{child=new GameObject(n.Children[i].Name);Add<RectTransform>(child).SetParent(go.transform,false);}Apply(n.Children[i],child,font,cardTemplate);}
   if(n.Button){var button=Add<Button>(go);button.onClick=new Button.ButtonClickedEvent();int code=FirstCode(n);if(code==0){var raw=go.GetComponentInParent<RawImage>();if(raw!=null)code=Code(raw);}if(code>0){int chosen=code;button.onClick.AddListener((UnityAction)(Action)(()=>Program.instance.ocgcore.GetUI<MDPro3.UI.ServantUI.OcgCoreUI>().CardDescription.Show(null,null,chosen,null)));}}
   go.SetActive(n.Active);
  }
  static int FirstCode(Node node){if(node.Raw!=null&&node.Raw.Code>0)return node.Raw.Code;foreach(var child in node.Children){int code=FirstCode(child);if(code>0)return code;}return 0;}
 }
 [HarmonyPatch(typeof(MDPro3.Duel.DuelMessage),nameof(MDPro3.Duel.DuelMessage.GameMessage_ReloadField))]class RestoreSavedLogContext{static void Prefix(Il2CppSystem.IO.BinaryReader reader,out NativeChainState.Link[] __state){__state=null;if(Host.Session==null)return;long position=reader.BaseStream.Position;try{__state=NativeChainState.Read(reader.ReadBytes((int)(reader.BaseStream.Length-position)).ToArray());}finally{reader.BaseStream.Position=position;}} static void Postfix(NativeChainState.Link[] __state){if(Host.Session!=null)NativeLogArchive.RestoreQueuedContext();NativeChainState.Restore(__state);}}
 [HarmonyPatch(typeof(TextureManager),nameof(TextureManager.LoadCardToRawImageWithoutMaterialAsync))]class TrackSavedLogCardImage{static void Prefix(RawImage rawImage,int code){if(Host.Session!=null)NativeLogArchive.Track(rawImage,code);}}
}
